import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"1、【乾】 乾下乾上","description":"周易口訣義 - 1、【乾】 乾下乾上","frontmatter":{"title":"1、【乾】 乾下乾上","description":"周易口訣義 - 1、【乾】 乾下乾上"},"headers":[],"relativePath":"classics/koujueyi/003.md","filePath":"classics/koujueyi/003.md"}'),r={name:"classics/koujueyi/003.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_1、【乾】-乾下乾上" tabindex="-1">1、【乾】 乾下乾上 <a class="header-anchor" href="#_1、【乾】-乾下乾上" aria-label="Permalink to “1、【乾】 乾下乾上”">​</a></h1><p>引讀</p><p>周易傳為上經第一者，先儒雲：「易有三名，夏曰連山，殷曰歸藏，周曰周易。」康成雲：「連山者，象山之出雲；歸藏者，莫不歸藏於其中；周易者，言易道周普，無所不備。」竊謂易者，是文王所演，因代為名，故稱周也。易取變通為義，上經者，三十卦，象陽，取其三之奇數也。經猶徑也，謂聖人亦以易道教人，可以踐履濟涉徑路，無所不通也。卦者，掛也，謂懸掛物象，吉凶之理顯焉。傳者，傳也，如孔氏傳之類也。</p><p>初九：潛龍勿用。</p><p>九二：見龍在田，利見大人。</p><p>九三：君子終日乾乾，夕惕若。厲，無咎。</p><p>九四：或躍在淵，無咎。</p><p>九五：飛龍在天，利見大人。</p><p>上九：亢龍，有悔。</p><p>用九：見群龍無首，吉。</p><p>彖曰：大哉乾元，萬物資始，乃統天。雲行雨施，品物流形。大明終始，六位時成，時乘六龍以御天。乾道變化，各正性命，保合太和，乃利貞。首出庶物，萬國咸寧。</p><p>象曰：天行健，君子以自強不息。「潛龍勿用」，陽在下也。</p><p>「見龍在田」，德施普也。</p><p>「終日乾乾」，反覆道也。</p><p>「或躍在淵」，進無咎也。</p><p>「飛龍在天」，大人造也。</p><p>「亢龍有悔」，盈不可久也。</p><p>「用九」，天德不可為首也。</p><p>解讀</p><p>「乾，元、亨、利、貞」者，乾，天也。天是體名，乾是用名。謂天體凝寂，非人所法，故聖人慾使人法天之用，不法天之體，故名之曰「乾」，而不名之曰天也。若「元、亨、利、貞」，此四者，亦是天之四德也。天以四時之氣，春生，秋殺，冬寒，夏暑，有此四時之義，故名為天也。周氏雲：元，始也，於時配春，言萬物始生，得其元始之序，發育長養。亨，通也，於時配夏，夏以通暢，合其嘉美之道。利者，義也，於時配秋，秋以成實，得其利物之宜。貞者，正也，於時配冬，冬以物之終，納幹正之道。若以五行言之，元，木也；亨，火也；利，金也；貞，水也。土則資運四事，故不言之。若以人事，則元為仁，亨為禮，利為義，貞為信。不言智者，謂此四事，因智而用。故乾鑿度雲：「水土二行，兼智兼信」是也。</p><p>「初九，潛龍勿用」者，潛，隱也。龍者，變化之物，喻天之陽氣。初九，建子之月，陽氣始動於地中，既未萌芽，猶是潛伏。比聖人有龍德，時未可行，惟宜潛藏，韜光遁世，故言「勿用」。</p><p>九二，見龍在田，利見大人。此當建醜之月，陽氣發見，文明顯著，故言「在田」也。「利見大人」者，此以人事明之，猶似聖人道德漸顯，為天下眾庶之所利見。若夫子教於洙泗，人虛往實歸，見者皆利，故稱「大人」。</p><p>九三，君子終日乾乾，夕惕者厲，無咎者，若，如也；厲，危也。既居下卦之上，不可驕盈，入上卦之下，心懷猶豫，故曰「終日乾乾」。從晝至夕，常懷憂惕，若有危厲，如此戒懼，乃得「無咎」。先儒雲：若文王反國，大釐政之日。</p><p>九四，或躍在淵，無咎。或，疑；躍，跳也。陽氣漸盛，猶龍躍在乎淵。如聖人位漸尊高，欲進王位，心懷疑慮，未敢果決，相時而動，故得「無咎」。若武王觀兵孟津，候時而進，合經常道，故「無咎」。</p><p>九五，飛龍在天，利見大人。如聖人有聖德而登盛位，為天下眾庶利見，故云「利見大人」。夫龍之為物，在地則行，在淵則躍，在天則飛。</p><p>上九，亢龍有悔。亢，極也，驕也。以陽氣盛極喻之。聖人久處君位，不能謙和自守，而為驕亢，故致悔恨。先儒雲：但九五之位，亦有大聖而居者，亦有非大聖而居者。非大聖而居者，不能免其憂悔，猶如堯之末年，四凶在朝，是以有悔。</p><p>用九，見群龍，無首，吉者，用，總也，此九陽之德也。謂聖人用此九陽之德，不可驕盈為物頭首，更在謙柔卑退，降情接下，如此乃吉，故曰「無首吉」也。</p><p>象曰：天行健，君子以自強不息。行者，運動之稱；健者，強壯之名。所以乾稱「健」者，以其運行不息，無時虧退。故宋衷雲：「晝夜不懈，以健詳其名。」餘卦各當名，不假於詳也。「君子以自強不息」者，凡言君子，聖賢之通呼。故堯舜一日萬幾，文王日昃不暇食，仲尼終夜不寢，顏子欲罷不能自已，蓋是修德乾乾，無時休息也。</p>',28)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
